/**
 * The Living Manifesto — GitHub-to-Cloudflare one-file deployment, v0.3.
 * GitHub remains source control; Cloudflare Pages securely serves UI + API on the SAME origin.
 * Cloudflare Pages build command: node deploy.mjs
 * Cloudflare Pages build output directory: dist
 * No API credentials, notes, or private content are embedded here.
 * Do NOT configure GitHub Pages to serve the contents of dist.
 */
import {mkdir,writeFile} from 'node:fs/promises';
import {gunzipSync} from 'node:zlib';
import {createHash} from 'node:crypto';
import {Buffer} from 'node:buffer';
const entries =
[
["_worker.js","","3e6d266af1b58698ebb97fd683e446351b925e2a378d1debdc945cd39ce38105"],
["index.html","","618e1ebefc1452fb85064b78288366f41d9067e90ce3a5b3de1f26d17a12b68a"],
["styles.css","","5d84b97d20efdb7ae140b41a3e36dadc96e738b0048886f5aedcf3bb373359b6"],
["app.js","","8ae5fdf366313a0e9d3c9f56d6052764cb4bce6ab10edaf801c5609039db04e4"],
["manifest.webmanifest","","7bf0277d73f618c7c76e7a27dba501effbe9ada344a5316054a0a3278353dd87"],
["service-worker.js","","1851111fd4398ca1e828457215693e8997b7133cc377c9c5eeaeb395601b9f2b"],
["icon-180.png","","9f2ed78e67796b87e56a32f4b974c8b42d7dbc7d2bfe137dc2a8e09d84fc9cb9"],
["icon-192.png","","9ae985585f36218e4f3634c480b0d02954d46e62df72f280b2c873b57495815b"],
["icon-512.png","","d33a7df296eeff7be392d8b903ac5fff1c6f961de2af3291439cd255fe0af3f0"],
["_headers","","377c696f6ef110d90a5215dcde8f78f91364cdea3840716dfb95655128e2008f"]
];
await mkdir('dist',{recursive:true});
for(const [name,gz,sha] of entries){
  const contents=gunzipSync(Buffer.from(gz,'base64'));
  if(createHash('sha256').update(contents).digest('hex')!==sha)throw new Error('Integrity verification failed: '+name);
  await writeFile('dist/'+name,contents);
  console.log('Prepared '+name+' ('+contents.byteLength+' bytes)');
}
console.log('Living Manifesto v0.3.1 ready for Cloudflare Workers. D1 schema initialization fixed.');
